-- pos-marketing: Flyway baseline (flattened 2026-09-09 from the previous migration history) with the
-- ADR-0062 tenancy schema folded in. Generated by scripts/db/tenancy/flatten.py from a pg_dump of a
-- database migrated with the retired scripts; the tenancy additions are mechanical and are listed in
-- docs/TENANCY_SCHEMA.md. Global (unscoped) tables: src/main/resources/db/tenancy-global-tables.txt.
--
-- Tenant context: app_current_tenant() reads the session setting app.current_tenant, which the
-- TenantAwareDataSource (pos-tenancy-common, plan WS1) binds per checkout. Until then the owner role
-- carries a transitional default (postgres/init-tenancy.sh) and tests set it per connection.
-- With nothing bound: NULL -> every scoped table reads as empty and refuses inserts (fail closed).

-- Functions are emitted before the tables they reference (pg_dump order); do not validate bodies.
SET check_function_bodies = false;

CREATE OR REPLACE FUNCTION public.app_current_tenant() RETURNS uuid
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$ SELECT NULLIF(current_setting('app.current_tenant', true), '')::uuid $$;

CREATE TABLE public.campaign (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    campaign_id uuid NOT NULL,
    code character varying(100) NOT NULL,
    name character varying(200) NOT NULL,
    description character varying(1000),
    audience_type character varying(20) NOT NULL,
    campaign_program_id uuid,
    status character varying(20) NOT NULL,
    segment_id uuid,
    promotion_offer_id uuid,
    catalog_focus_ref character varying(200),
    window_start timestamp(6) with time zone,
    window_end timestamp(6) with time zone,
    schedule_type character varying(20) NOT NULL,
    scheduled_at timestamp(6) with time zone,
    email_template_id uuid,
    sms_template_id uuid,
    created_by character varying(255),
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT campaign_audience_type_chk CHECK (((audience_type)::text = ANY ((ARRAY['COMMERCIAL'::character varying, 'INDIVIDUAL'::character varying])::text[]))),
    CONSTRAINT campaign_schedule_type_chk CHECK (((schedule_type)::text = ANY ((ARRAY['IMMEDIATE'::character varying, 'SCHEDULED'::character varying])::text[]))),
    CONSTRAINT campaign_scheduled_at_chk CHECK ((((schedule_type)::text <> 'SCHEDULED'::text) OR (scheduled_at IS NOT NULL))),
    CONSTRAINT campaign_status_chk CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'SCHEDULED'::character varying, 'SENDING'::character varying, 'SENT'::character varying, 'PAUSED'::character varying, 'CANCELLED'::character varying, 'CLOSED'::character varying])::text[]))),
    CONSTRAINT campaign_window_chk CHECK (((window_end IS NULL) OR (window_start IS NULL) OR (window_end >= window_start)))
);

CREATE TABLE public.campaign_attribution (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    redemption_id uuid NOT NULL,
    campaign_id uuid NOT NULL,
    campaign_code character varying(100) NOT NULL,
    party_id uuid NOT NULL,
    workorder_id uuid,
    discount_amount numeric(19,4),
    attributed_at timestamp(6) with time zone NOT NULL
);

CREATE TABLE public.campaign_audience_member (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    audience_member_id uuid NOT NULL,
    campaign_id uuid NOT NULL,
    party_id uuid NOT NULL,
    resolved_at timestamp(6) with time zone NOT NULL,
    truncated boolean DEFAULT false NOT NULL
);

CREATE TABLE public.campaign_channel (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    campaign_id uuid NOT NULL,
    channel character varying(20) NOT NULL,
    CONSTRAINT campaign_channel_chk CHECK (((channel)::text = ANY ((ARRAY['EMAIL'::character varying, 'SMS'::character varying])::text[])))
);

CREATE TABLE public.campaign_send (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    campaign_send_id uuid NOT NULL,
    campaign_id uuid NOT NULL,
    recipient_party_id uuid NOT NULL,
    contact_id uuid,
    channel character varying(20) NOT NULL,
    address_hash character varying(64),
    status character varying(20) NOT NULL,
    failure_reason character varying(500),
    provider_message_id character varying(200),
    attempts integer DEFAULT 0 NOT NULL,
    queued_at timestamp(6) with time zone NOT NULL,
    sent_at timestamp(6) with time zone,
    delivered_at timestamp(6) with time zone,
    updated_at timestamp(6) with time zone NOT NULL,
    opened_at timestamp(6) with time zone,
    clicked_at timestamp(6) with time zone,
    CONSTRAINT campaign_send_channel_chk CHECK (((channel)::text = ANY ((ARRAY['EMAIL'::character varying, 'SMS'::character varying])::text[]))),
    CONSTRAINT campaign_send_status_chk CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'SENT'::character varying, 'DELIVERED'::character varying, 'BOUNCED'::character varying, 'COMPLAINED'::character varying, 'SUPPRESSED'::character varying, 'FAILED'::character varying])::text[])))
);

CREATE TABLE public.event_outbox (
    id uuid NOT NULL,
    topic character varying(255) NOT NULL,
    record_key character varying(255) NOT NULL,
    payload text NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    published_at timestamp(6) with time zone,
    attempts integer DEFAULT 0 NOT NULL,
    last_error text
);

CREATE TABLE public.ext_catalog (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    catalog_item_id uuid NOT NULL,
    item_kind character varying(16) NOT NULL,
    name character varying(512),
    sku character varying(128),
    category_id uuid,
    category character varying(255),
    active boolean DEFAULT true NOT NULL,
    aggregate_version bigint NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT ext_catalog_item_kind_chk CHECK (((item_kind)::text = ANY ((ARRAY['PRODUCT'::character varying, 'SERVICE'::character varying])::text[])))
);

CREATE TABLE public.ext_party_consent (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    consent_key character varying(60) NOT NULL,
    party_id uuid NOT NULL,
    channel character varying(20) NOT NULL,
    allowed boolean NOT NULL,
    reason character varying(40) NOT NULL,
    governing_party_id uuid,
    decided_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT ext_party_consent_channel_chk CHECK (((channel)::text = ANY ((ARRAY['EMAIL'::character varying, 'SMS'::character varying])::text[])))
);

CREATE TABLE public.ext_segment (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    segment_id uuid NOT NULL,
    name character varying(150),
    audience_type character varying(20),
    type character varying(20),
    active boolean DEFAULT false NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL
);

CREATE TABLE public.ext_suppression (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    suppression_key character varying(80) NOT NULL,
    channel character varying(20) NOT NULL,
    address_hash character varying(64) NOT NULL,
    party_id uuid,
    reason character varying(30),
    updated_at timestamp(6) with time zone NOT NULL
);

CREATE TABLE public.message_template (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    template_id uuid NOT NULL,
    name character varying(150) NOT NULL,
    channel character varying(20) NOT NULL,
    audience_type character varying(20) NOT NULL,
    subject character varying(255),
    body text NOT NULL,
    created_by character varying(255),
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT message_template_audience_type_chk CHECK (((audience_type)::text = ANY ((ARRAY['COMMERCIAL'::character varying, 'INDIVIDUAL'::character varying])::text[]))),
    CONSTRAINT message_template_channel_chk CHECK (((channel)::text = ANY ((ARRAY['EMAIL'::character varying, 'SMS'::character varying])::text[]))),
    CONSTRAINT message_template_subject_chk CHECK ((((channel)::text <> 'EMAIL'::text) OR (subject IS NOT NULL)))
);

CREATE TABLE public.processed_events (
    event_id character varying(36) NOT NULL,
    tenant_id uuid,
    owner character varying(64) NOT NULL,
    processed_at timestamp(6) with time zone NOT NULL
);

