ALTER TABLE ONLY public.campaign_send
    ADD CONSTRAINT uq_campaign_send_recipient UNIQUE (tenant_id, campaign_id, recipient_party_id, channel);

CREATE INDEX idx_campaign_attribution_campaign ON public.campaign_attribution USING btree (campaign_id);

CREATE INDEX idx_campaign_audience_campaign ON public.campaign_audience_member USING btree (campaign_id);

CREATE INDEX idx_campaign_program ON public.campaign USING btree (campaign_program_id);

CREATE INDEX idx_campaign_segment ON public.campaign USING btree (segment_id);

CREATE INDEX idx_campaign_send_campaign ON public.campaign_send USING btree (campaign_id, status);

CREATE INDEX idx_campaign_send_pending ON public.campaign_send USING btree (status, queued_at);

CREATE INDEX idx_campaign_send_provider_message ON public.campaign_send USING btree (provider_message_id);

CREATE INDEX idx_campaign_status ON public.campaign USING btree (status);

CREATE INDEX idx_event_outbox_unpublished ON public.event_outbox USING btree (published_at, id);

CREATE INDEX idx_ext_catalog_category_id ON public.ext_catalog USING btree (category_id);

CREATE INDEX idx_ext_catalog_category_name ON public.ext_catalog USING btree (lower((category)::text));

CREATE INDEX idx_ext_catalog_kind_name ON public.ext_catalog USING btree (item_kind, lower((name)::text));

CREATE INDEX idx_ext_catalog_sku ON public.ext_catalog USING btree (lower((sku)::text));

CREATE INDEX idx_ext_party_consent_decided ON public.ext_party_consent USING btree (decided_at);

CREATE INDEX idx_ext_party_consent_lookup ON public.ext_party_consent USING btree (party_id, channel);

CREATE INDEX idx_ext_suppression_lookup ON public.ext_suppression USING btree (channel, address_hash);

CREATE INDEX idx_ext_suppression_party ON public.ext_suppression USING btree (party_id);

CREATE INDEX idx_message_template_channel ON public.message_template USING btree (channel, audience_type);

CREATE INDEX idx_processed_events_owner_tenant_event ON public.processed_events USING btree (owner, tenant_id, event_id);

CREATE UNIQUE INDEX uq_campaign_code ON public.campaign USING btree (tenant_id, lower((code)::text));

CREATE UNIQUE INDEX uq_message_template_name ON public.message_template USING btree (tenant_id, lower((name)::text));

